// Verification-only value IR. This deliberately omits phase and is NEVER a
// submitted quantum circuit or a resource score. No nonce is screened here.
mod io;
use quantum_ecc::circuit::{Op,OperationType as K,analyze_ops};
use std::collections::{BTreeSet,HashMap};
const NO:u32=u32::MAX;
const QX:u8=0;const QCX:u8=1;const QCCX:u8=2;const QSWAP:u8=3;const QZERO:u8=4;
const CINV:u8=5;const CZERO:u8=6;const CONE:u8=7;const CRNG:u8=8;
#[derive(Clone,Copy,Debug)]struct Node{k:u8,a:u32,b:u32,t:u32,g:u32,r:u32,source:u32}
struct Program{nodes:Vec<Node>,guards:Vec<Vec<u32>>,nq:usize,nb:usize,versions:usize,rng:usize,certified_zero_resets:usize}
fn merge(a:&[u32],b:&[u32])->Vec<u32>{let mut x=a.to_vec();x.extend_from_slice(b);x.sort_unstable();x.dedup();x}
fn intersect(a:&[u32],b:&[u32])->Vec<u32>{a.iter().copied().filter(|v|b.binary_search(v).is_ok()).collect()}
fn subset(a:&[u32],b:&[u32])->bool{a.iter().all(|v|b.binary_search(v).is_ok())}
fn intern(v:Vec<u32>,rows:&mut Vec<Vec<u32>>,index:&mut HashMap<Vec<u32>,u32>)->u32{if let Some(&id)=index.get(&v){return id;}let id=u32::try_from(rows.len()).unwrap();rows.push(v.clone());index.insert(v,id);id}
fn compile(ops:&[Op],unknown_quantum:&[usize])->Program{let(_,nb,_,_)=analyze_ops(ops.iter());compile_known(ops,unknown_quantum,&(0..nb as usize).collect::<Vec<_>>())}
fn compile_known(ops:&[Op],unknown_quantum:&[usize],unknown_classical:&[usize])->Program{
 let(nq,nb,_,_)=analyze_ops(ops.iter());let(nq,nb)=(nq as usize,nb as usize);let mut constants=vec![0i8;nb];for &b in unknown_classical{constants[b]=-1;}let mut versions=nb;let mut current:Vec<u32>=(0..nb).map(|i|i.try_into().unwrap()).collect();let mut guards=vec![vec![]];let mut index=HashMap::from([(vec![],0)]);let mut base=0u32;let mut stack=vec![];let mut nodes=Vec::with_capacity(ops.len());let mut zero=vec![true;nq];let mut meet=vec![Vec::<u32>::new();nq];for &q in unknown_quantum{zero[q]=false;}let mut rng=0usize;let mut certified=0;
 for(i,o)in ops.iter().enumerate(){let condition=if o.c_condition.0==u64::MAX{None}else{Some(current[o.c_condition.0 as usize])};let false_guard=base==NO||condition.map(|v|constants[v as usize]==0).unwrap_or(false);let own=condition.filter(|&v|constants[v as usize]!=1).map(|v|vec![v]).unwrap_or_default();let g=if false_guard{NO}else{intern(merge(&guards[base as usize],&own),&mut guards,&mut index)};
  if o.kind==K::PushCondition{stack.push(base);base=g;continue;}if o.kind==K::PopCondition{base=stack.pop().unwrap();continue;}
  if g==NO{if matches!(o.kind,K::R|K::Hmr){rng+=1;}continue;}let mut qnode=None;
  match o.kind{
   K::PushCondition=>{stack.push(base);base=g;},K::PopCondition=>base=stack.pop().unwrap(),
   K::X=>qnode=Some((QX,NO,NO,o.q_target.0 as u32,g)),
   K::CX=>qnode=Some((QCX,o.q_control1.0 as u32,NO,o.q_target.0 as u32,g)),
   K::CCX=>qnode=Some((QCCX,o.q_control1.0 as u32,o.q_control2.0 as u32,o.q_target.0 as u32,g)),
   K::Swap=>qnode=Some((QSWAP,o.q_control1.0 as u32,NO,o.q_target.0 as u32,g)),
   K::R|K::Hmr=>{let t=o.q_target.0 as usize;let global=zero[t]||subset(&guards[g as usize],&meet[t]);if global{certified+=1;zero[t]=true;meet[t].clear();}qnode=Some((QZERO,NO,NO,t as u32,if global{0}else{g}));},
   K::BitInvert|K::BitStore0|K::BitStore1=>{},
   K::Neg|K::Z|K::CZ|K::CCZ|K::Register|K::AppendToRegister|K::DebugPrint=>{},
  }
  if matches!(o.kind,K::BitInvert|K::BitStore0|K::BitStore1|K::Hmr){let bit=o.c_target.0 as usize;let old=current[bit];let new:u32=versions.try_into().unwrap();versions+=1;current[bit]=new;let k=match o.kind{K::BitInvert=>CINV,K::BitStore0=>CZERO,K::BitStore1=>CONE,K::Hmr=>CRNG,_=>unreachable!()};let old_constant=constants[old as usize];let constant=match k{CZERO=>if g==0||old_constant==0{0}else{-1},CONE=>if g==0||old_constant==1{1}else{-1},CINV=>if g==0&&old_constant>=0{1-old_constant}else{-1},CRNG=>-1,_=>unreachable!()};constants.push(constant);nodes.push(Node{k,a:old,b:NO,t:new,g,r:rng.try_into().unwrap(),source:i.try_into().unwrap()});}
  if let Some((k,a,b,t,qg))=qnode{if matches!(k,QCX|QCCX){assert_ne!(t,a,"Value gate cancellation requires distinct target/control");if k==QCCX{assert_ne!(t,b);}}if k!=QZERO{let mut writes=vec![t as usize];if k==QSWAP{writes.push(a as usize);}for q in writes{if zero[q]{meet[q]=guards[g as usize].clone();zero[q]=false;}else{meet[q]=intersect(&meet[q],&guards[g as usize]);}}}nodes.push(Node{k,a,b,t,g:qg,r:NO,source:i.try_into().unwrap()});}
  if matches!(o.kind,K::R|K::Hmr){rng+=1;}
 }
 assert!(stack.is_empty());Program{nodes,guards,nq,nb,versions,rng,certified_zero_resets:certified}
}
fn live(p:&mut Program,outputs:&[usize])->usize{let mut q=vec![false;p.nq];for &x in outputs{q[x]=true;}let mut c=vec![false;p.versions];let mut keep=vec![false;p.nodes.len()];for(i,n)in p.nodes.iter().enumerate().rev(){let mut yes=false;if n.k>=CINV{if c[n.t as usize]{yes=true;if n.k==CINV||n.g!=0{c[n.a as usize]=true;}}}else if n.k==QSWAP{if q[n.a as usize]||q[n.t as usize]{yes=true;q[n.a as usize]=true;q[n.t as usize]=true;}}else if q[n.t as usize]{yes=true;match n.k{QX=>{},QCX=>q[n.a as usize]=true,QCCX=>{q[n.a as usize]=true;q[n.b as usize]=true;},QZERO=>{if n.g==0{q[n.t as usize]=false;}},_=>unreachable!()}}
  if yes{keep[i]=true;for &v in &p.guards[n.g as usize]{c[v as usize]=true;}}
 }let before=p.nodes.len();p.nodes=std::mem::take(&mut p.nodes).into_iter().zip(keep).filter_map(|(n,k)|k.then_some(n)).collect();before-p.nodes.len()}
fn parts(n:&Node)->Vec<usize>{let mut v=vec![n.t as usize];if matches!(n.k,QCX|QCCX|QSWAP){v.push(n.a as usize);}if n.k==QCCX{v.push(n.b as usize);}v.sort_unstable();v.dedup();v}
fn cancel(p:&mut Program)->usize{
 let mut touch=vec![usize::MAX;p.nq];let mut write=touch.clone();let mut prior_touch=vec![[usize::MAX;3];p.nodes.len()];let mut prior_write=prior_touch.clone();let mut alive=vec![true;p.nodes.len()];let mut pending:HashMap<(u8,u32,u32,u32,u32),usize>=HashMap::new();let mut removed=0;
 for(i,n)in p.nodes.iter().enumerate(){if n.k>=CINV{continue;}let qs=parts(n);
  for &q in &qs{while touch[q]!=usize::MAX&&!alive[touch[q]]{let j=touch[q];let pos=parts(&p.nodes[j]).iter().position(|&x|x==q).unwrap();touch[q]=prior_touch[j][pos];}while write[q]!=usize::MAX&&!alive[write[q]]{let j=write[q];let pos=parts(&p.nodes[j]).iter().position(|&x|x==q).unwrap();write[q]=prior_write[j][pos];}}
  let targets=if n.k==QSWAP{vec![n.t as usize,n.a as usize]}else{vec![n.t as usize]};let controls:Vec<_>=qs.iter().copied().filter(|q|!targets.contains(q)).collect();let key=(n.k,n.a,n.b,n.t,n.g);
  if n.k<QZERO{if let Some(&j)=pending.get(&key){if alive[j]&&targets.iter().all(|&q|touch[q]==j)&&controls.iter().all(|&q|write[q]==usize::MAX||write[q]<j){alive[j]=false;alive[i]=false;removed+=2;pending.remove(&key);continue;}}pending.insert(key,i);}
  for(j,&q)in qs.iter().enumerate(){prior_touch[i][j]=touch[q];prior_write[i][j]=write[q];touch[q]=i;if targets.contains(&q){write[q]=i;}}
 }p.nodes=std::mem::take(&mut p.nodes).into_iter().zip(alive).filter_map(|(n,k)|k.then_some(n)).collect();removed}
fn optimize(p:&mut Program,outputs:&[usize])->Vec<(usize,usize,usize)>{let mut rounds=vec![];for round in 0..128{let l=live(p,outputs);let c=cancel(p);rounds.push((l,c,p.nodes.len()));if round%8==0{eprintln!("VALUE_IR_PROGRESS round={} nodes={} removed={} cancelled={}",round,p.nodes.len(),l,c);}if l+c==0{break;}}rounds}
fn eval(p:&Program,q:&mut[u64],initial_bits:&[u64],random:&[u64]){assert_eq!(initial_bits.len(),p.nb);assert_eq!(random.len(),p.rng);let mut c=vec![0;p.versions];c[..p.nb].copy_from_slice(initial_bits);for n in &p.nodes{let g=p.guards[n.g as usize].iter().fold(u64::MAX,|g,&v|g&c[v as usize]);let t=n.t as usize;match n.k{QX=>q[t]^=g,QCX=>q[t]^=g&q[n.a as usize],QCCX=>q[t]^=g&q[n.a as usize]&q[n.b as usize],QSWAP=>{let v=(q[t]^q[n.a as usize])&g;q[t]^=v;q[n.a as usize]^=v;},QZERO=>q[t]&=!g,CINV=>c[t]=c[n.a as usize]^g,CZERO=>c[t]=c[n.a as usize]&!g,CONE=>c[t]=c[n.a as usize]|g,CRNG=>c[t]=(c[n.a as usize]&!g)|(random[n.r as usize]&g),_=>unreachable!()}}}
fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),3);let ops=io::load_ops(&args[1]);let outputs:Vec<_>=ops.iter().filter(|o|o.kind==K::AppendToRegister&&o.q_target.0!=u64::MAX).map(|o|o.q_target.0 as usize).collect::<BTreeSet<_>>().into_iter().collect();assert_eq!(outputs.len(),512);let unknown_bits:Vec<_>=ops.iter().filter(|o|o.kind==K::AppendToRegister&&o.c_target.0!=u64::MAX).map(|o|o.c_target.0 as usize).collect::<BTreeSet<_>>().into_iter().collect();let mut p=compile_known(&ops,&outputs,&unknown_bits);let initial=p.nodes.len();let rounds=optimize(&mut p,&outputs);let live_random=p.nodes.iter().filter(|n|n.k==CRNG).count();let final_t=p.nodes.iter().filter(|n|n.k==QCCX).count();let result=serde_json::json!({"status":"VERIFICATION_ONLY_VALUE_IR_AUDIT_NOT_A_QUANTUM_CANDIDATE_OR_NONCE_SCREEN","original_operations":ops.len(),"initial_value_nodes":initial,"final_value_nodes":p.nodes.len(),"remaining_value_ccx_nodes":final_t,"live_random_measurement_definitions":live_random,"original_rng_words":p.rng,"captured_guard_rows":p.guards.len(),"classical_ssa_versions":p.versions,"certified_global_zero_resets":p.certified_zero_resets,"rounds":rounds,"outputs":outputs.len(),"scope":"Captured SSA guard clauses and guarded-write dominance certify resets as globally zero under helper-zero initial state. Values-only IR liveness and read/write-commuting equal-guard self-inverse cancellation. Phase deliberately omitted, so IR counts are NEVER quantum resource scores. No nonce rejected or candidate changed; full protected qualification required before any future rejection filter."});std::fs::write(&args[2],serde_json::to_string_pretty(&result).unwrap()+"\n").unwrap();println!("{result}");}
#[cfg(test)]mod tests{
 use super::*;use quantum_ecc::circuit::{QubitId,BitId};use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;
 struct Words{v:Vec<u8>,at:usize}impl XofReader for Words{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.v[self.at..self.at+b.len()]);self.at+=b.len();}}
 fn op(k:K,a:u64,b:u64,t:u64,ct:u64,cc:u64)->Op{let mut o=Op::empty();o.kind=k;o.q_control2=QubitId(a);o.q_control1=QubitId(b);o.q_target=QubitId(t);o.c_target=BitId(ct);o.c_condition=BitId(cc);o.validate();o}
 fn checked(ops:&[Op],inputs:&[usize],outputs:&[usize])->Program{let mut p=compile(ops,inputs);optimize(&mut p,outputs);for mode in 0..(p.rng+4){let words:Vec<_>=(0..p.rng).map(|j|match mode{0=>0,1=>u64::MAX,2=>0xa55a_dd33_ff00_1701,3=>0x9e3779b97f4a7c15u64.wrapping_mul((j+1)as u64).rotate_left((j%64)as u32),_=>if j==mode-4{u64::MAX}else{0}}).collect();let mut rng=Words{v:words.iter().flat_map(|w|w.to_le_bytes()).collect(),at:0};let mut sim=Simulator::new(p.nq,p.nb,&mut rng);for lane in 0..64{for(i,&q)in inputs.iter().enumerate(){sim.qubits[q]|=((lane>>i&1)as u64)<<lane;}for bit in 0..p.nb{sim.bits[bit]|=((lane>>((bit%2)+inputs.len())&1)as u64)<<lane;}}let mut q=sim.qubits.clone();let bits=sim.bits.clone();sim.apply_iter(ops.iter());eval(&p,&mut q,&bits,&words);for &x in outputs{assert_eq!(q[x],sim.qubits[x],"mode{mode} output{x}");}drop(sim);assert_eq!(rng.at,p.rng*8);}p}
 #[test]fn dominated_conditional_reset_and_frames_remove_only_value_dead_rng(){let n=u64::MAX;let ops=vec![op(K::PushCondition,n,n,n,n,0),op(K::CX,n,0,1,n,n),op(K::CCX,0,1,3,n,n),op(K::CX,n,0,1,n,n),op(K::Hmr,n,n,3,1,n),op(K::CZ,n,0,1,n,1),op(K::PopCondition,n,n,n,n,n),op(K::CX,n,1,2,n,n)];let p=checked(&ops,&[0,1,2],&[0,1,2]);assert_eq!(p.nodes.iter().filter(|n|n.k==CRNG).count(),0);assert_eq!(p.nodes.iter().filter(|n|n.k==QCCX).count(),0);}
 #[test]fn unmatched_reset_guard_never_claims_global_zero(){let n=u64::MAX;let ops=vec![op(K::CCX,0,1,3,n,0),op(K::Hmr,n,n,3,2,1),op(K::CX,n,3,2,n,n)];let p=checked(&ops,&[0,1,2],&[0,1,2]);assert!(p.nodes.iter().any(|n|n.k==QZERO&&n.g!=0));assert!(p.nodes.iter().any(|n|n.k==QCCX));}
 #[test]fn prepared_arbitrary_nonoutput_input_is_not_assumed_clean(){let n=u64::MAX;let ops=vec![op(K::Hmr,n,n,3,1,0),op(K::CX,n,3,2,n,n)];let p=checked(&ops,&[0,1,2,3],&[0,1,2]);assert!(p.nodes.iter().any(|n|n.k==QZERO&&n.g!=0));}
 #[test]fn captured_guard_versions_survive_mutation_and_allow_only_correct_cancellation(){let n=u64::MAX;let ops=vec![op(K::PushCondition,n,n,n,n,0),op(K::CX,n,0,2,n,n),op(K::BitInvert,n,n,n,0,n),op(K::CX,n,0,2,n,n),op(K::PopCondition,n,n,n,n,n),op(K::X,n,n,2,n,0)];checked(&ops,&[0,1,2],&[0,1,2]);}
 #[test]fn changed_per_op_guard_prevents_false_gate_cancellation(){let n=u64::MAX;let ops=vec![op(K::CX,n,0,2,n,0),op(K::BitInvert,n,n,n,0,n),op(K::CX,n,0,2,n,0)];let p=checked(&ops,&[0,1,2],&[0,1,2]);assert_eq!(p.nodes.iter().filter(|n|n.k==QCX).count(),2);}
 #[test]fn genuinely_live_measurement_keeps_exact_original_rng_slot(){let n=u64::MAX;let ops=vec![op(K::R,n,n,4,n,n),op(K::Hmr,n,n,3,1,n),op(K::X,n,n,2,n,1)];let p=checked(&ops,&[0,1,2],&[0,1,2]);let live:Vec<_>=p.nodes.iter().filter(|n|n.k==CRNG).collect();assert_eq!(live.len(),1);assert_eq!(live[0].r,1);}
 #[test]fn missing_guard_or_reset_is_detected_by_protected_value_comparison(){let n=u64::MAX;let ops=vec![op(K::CCX,0,1,3,n,0),op(K::Hmr,n,n,3,1,1),op(K::CX,n,3,2,n,n)];let mut p=compile(&ops,&[0,1,2]);optimize(&mut p,&[0,1,2]);let before=p.nodes.len();p.nodes.retain(|x|x.k!=QZERO);assert!(p.nodes.len()<before);let mut caught=false;for mode in[0,u64::MAX]{let mut rng=Words{v:mode.to_le_bytes().to_vec(),at:0};let mut sim=Simulator::new(p.nq,p.nb,&mut rng);sim.qubits[0]=u64::MAX;sim.qubits[1]=u64::MAX;sim.bits[0]=u64::MAX;sim.bits[1]=u64::MAX;let mut q=sim.qubits.clone();let bits=sim.bits.clone();sim.apply_iter(ops.iter());eval(&p,&mut q,&bits,&[mode]);caught|=q[2]!=sim.qubits[2];}assert!(caught);}
 #[test]fn shared_read_only_control_commutes_but_target_reads_and_control_writes_block(){let n=u64::MAX;let ops=vec![op(K::CX,n,0,2,n,n),op(K::CX,n,0,1,n,n),op(K::CX,n,0,2,n,n),op(K::CX,n,2,1,n,n),op(K::CX,n,0,2,n,n),op(K::X,n,n,0,n,n),op(K::CX,n,0,2,n,n)];let mut p=compile(&ops,&[0,1,2]);assert_eq!(cancel(&mut p),2);checked(&ops,&[0,1,2],&[0,1,2]);}

 fn checked_known_bits(ops:&[Op],unknown_bits:&[usize])->Program{let inputs=[0,1,2];let mut p=compile_known(ops,&inputs,unknown_bits);optimize(&mut p,&inputs);for pattern in[0u64,u64::MAX,0xa55a_3311_ee00_1701]{let words=vec![pattern;p.rng];let mut rng=Words{v:words.iter().flat_map(|x|x.to_le_bytes()).collect(),at:0};let mut sim=Simulator::new(p.nq,p.nb,&mut rng);for lane in 0..64{for(i,&q)in inputs.iter().enumerate(){sim.qubits[q]|=((lane>>i&1)as u64)<<lane;}for(i,&b)in unknown_bits.iter().enumerate(){sim.bits[b]|=((lane>>(i+3)&1)as u64)<<lane;}}let mut q=sim.qubits.clone();let bits=sim.bits.clone();sim.apply_iter(ops.iter());eval(&p,&mut q,&bits,&words);for &q0 in &inputs{assert_eq!(q[q0],sim.qubits[q0]);}drop(sim);assert_eq!(rng.at,p.rng*8);}p}
 #[test]fn helper_bits_initial_zero_false_hmr_keeps_rng_position(){let n=u64::MAX;let ops=vec![op(K::Hmr,n,n,3,2,1),op(K::BitStore1,n,n,n,1,n),op(K::Hmr,n,n,3,2,1),op(K::X,n,n,2,n,2)];let p=checked_known_bits(&ops,&[0]);let live:Vec<_>=p.nodes.iter().filter(|n|n.k==CRNG).collect();assert_eq!(p.rng,2);assert_eq!(live.len(),1);assert_eq!(live[0].r,1);}
 #[test]fn known_bit_stores_and_captured_false_guard_preserve_values(){let n=u64::MAX;let ops=vec![op(K::PushCondition,n,n,n,n,1),op(K::BitStore1,n,n,n,1,n),op(K::X,n,n,2,n,n),op(K::PopCondition,n,n,n,n,n),op(K::BitStore1,n,n,n,1,0),op(K::X,n,n,2,n,1),op(K::BitStore0,n,n,n,1,n),op(K::BitInvert,n,n,n,1,n),op(K::CX,n,0,2,n,1)];checked_known_bits(&ops,&[0]);}

}
